SELECT kb.*, COUNT(d.id) AS document_count FROM knowledge_bases kb LEFT JOIN documents d ON d.knowledge_base_id = kb.id
LOWER(kb.name) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(COALESCE(kb.embedding_model, '')) LIKE CONCAT('%', LOWER(#{query}), '%')
GROUP BY kb.id ORDER BY kb.created_at DESC, kb.id LIMIT #{limit} OFFSET #{offset}
